    m.clim = climBuf; m.per = meta.perMonth;
    const N = m.N, nx = m.nx, ny = m.ny;
    m.H = climBuf.subarray(12 * m.per, 12 * m.per + N);
    m.LF = climBuf.subarray(12 * m.per + N, 12 * m.per + 2 * N);
    m.rng = mulberry32(opts.seed ?? ((Math.random() * 2 ** 32) >>> 0));
    m.dt = opts.dt ?? 200;
    // geometry
    m.lat = new Float64Array(ny); m.lon = new Float64Array(nx);
    for (let j = 0; j < ny; j++) m.lat[j] = m.lat0 + j * m.res;
    for (let i = 0; i < nx; i++) m.lon[i] = m.lon0 + i * m.res;
    const dl = m.res * DEG;
    m.cosj = new Float64Array(ny); m.tanj = new Float64Array(ny); m.fj = new Float64Array(ny); m.rdx = new Float64Array(ny);
    for (let j = 0; j < ny; j++) {
      const p = m.lat[j] * DEG; m.cosj[j] = Math.cos(p); m.tanj[j] = Math.tan(p); m.fj[j] = 2 * OMEGA * Math.sin(p);
      m.rdx[j] = 1 / (2 * A_E * m.cosj[j] * dl);
    }
