    m.zfilt = new Int32Array(ny); m.zfrac = new Float32Array(ny);
    const cref = Math.cos(48 * DEG);
    { const cr = Math.cos(38 * DEG); // continuous polar-type filter poleward of 38N (CFL safety)
      for (let j = 0; j < ny; j++) { const x = m.cosj[j] < cr ? 1.5 * ((cr / m.cosj[j]) ** 2 - 1) : 0; m.zfilt[j] = Math.floor(x); m.zfrac[j] = x - Math.floor(x); } }
    // arrays
    const KN = K * N;
    const mk = () => new Float32Array(KN);
    m.u0 = mk(); m.v0 = mk(); m.T0 = mk(); m.p0 = new Float32Array(N); // X'(n-1)
    m.u1 = mk(); m.v1 = mk(); m.T1 = mk(); m.p1 = new Float32Array(N); // X'(n)
    m.u2 = mk(); m.v2 = mk(); m.T2 = mk(); m.p2 = new Float32Array(N); // X'(n+1)
