    m.Ncu = mk(); m.Ncv = mk(); m.NcT = mk(); m.Ncp = new Float32Array(N); m.Ncw = mk(); m.NcPhi = mk();
    m.tu = mk(); m.tv = mk(); m.tT = mk(); m.tp = new Float32Array(N); m.tw = mk(); m.tPhi = mk(); // work tendencies
    m.su = mk(); m.sv = mk(); m.sT = mk(); m.sp = new Float32Array(N); // total state scratch
    m.G = mk(); m.Aa = mk(); m.Phi = mk(); m.sdI = new Float32Array((K + 1) * N);
    m.fu = mk(); m.fv = mk(); m.fT = mk(); // physics/forcing tendencies (anomaly)
    m.prec = new Float32Array(N); m.precOut = new Float32Array(N); m.precRun = new Float32Array(N); m.precRunInit = false; m.precC = new Float32Array(N); m.sstA = new Float32Array(N);
    m.bfu = mk(); m.bfv = mk(); m.bfT = mk(); m.nfu = mk(); m.nfv = mk(); m.nfT = mk(); m.nfp = new Float32Array(N); m.hdu = mk(); m.hdv = mk(); m.hdT = mk(); m.hdp = new Float32Array(N); m.sfu = mk(); m.sfv = mk(); m.sfT = mk(); m.pcInv = new Float32Array(N); m.sm1 = new Float32Array(N); m.sm2 = new Float32Array(N); m.omg = new Float32Array(N); m.omg2 = new Float32Array(N); m.conv = new Float32Array(N); m.tropQ = new Float32Array(N); m.convT = new Float32Array(N);
    m.tmp = new Float32Array(Math.max(nx, ny) + 4); m.lap = new Float32Array(N); m.lap2 = new Float32Array(N);
    // sponge
    m.sponge = new Float32Array(N); const spI = [], spC = [];
