    for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
      const d = Math.min(i, j, nx - 1 - i, ny - 1 - j);
      m.sponge[j * nx + i] = d >= W ? 0 : ((W - d) / W) ** 2 / 3600;
      if (d < W) { spI.push(j * nx + i); spC.push(((W - d) / W) ** 2 / 3600); }
    }
    m.spIdx = Int32Array.from(spI); m.spC = Float32Array.from(spC);
    const edge = []; for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) if (i === 0 || j === 0 || i === nx - 1 || j === ny - 1) edge.push(j * nx + i);
    m.edge = Int32Array.from(edge);
    // surface pressure from terrain (for orographic blocking)
    m.psfc = new Float32Array(N);
    for (let n = 0; n < N; n++) m.psfc[n] = 1013 * Math.exp(-m.H[n] / 8000);
    m.blk = new Float32Array(KN);
    for (let k = 0; k < K; k++) for (let n = 0; n < N; n++) {
      const under = (m.levs[k] - (m.psfc[n] - 40)) / 60; // >0 means level below/near terrain
      m.blk[k * N + n] = under <= 0 ? 0 : Math.min(1, under) / (4 * 3600);
    }
    m.cRF = new Float32Array(KN); m.cRT = new Float32Array(KN); m.cTT = new Float32Array(KN);
